function DropItemGroup:RefreshGroup(questId)
    self.questId = questId
    local rewardDataList = RewardConfMgr:GetInstance():GetTeamShowRewardData(questId)
    
    print("奖励1", table.dump(rewardDataList, nil, 3))

    local rewardDataMap = {}
    for i, rewardData in ipairs(rewardDataList) do
        local type = checkNumber(rewardData.type)
        if isNull(rewardDataMap[type]) then
            rewardDataMap[type] = {}
        end
        table.insert(rewardDataMap[type], rewardData)
    end

    print("奖励2", table.dump(rewardDataMap, nil, 3))

    self:RefreshMustDropItems(rewardDataMap[Constants.RewardSourceType.Certain])
    self:RefreshProbabilityDropItems(rewardDataMap[Constants.RewardSourceType.Probabilistic])
end

function DropItemGroup:RefreshMustDropItems(datas)
    datas = checkTable(datas)
    if table.count(datas) == 0 then return end

    ---@type CommonGoodsListLight
    local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight, "Game.Behaviours.CommonGoodsListLight")
    if isNotNull(scr) then
        scr:FreshBaseUI(datas, nil, nil, nil, nil, nil, nil, false)
    end
end

function DropItemGroup:RefreshProbabilityDropItems(datas)
    local prefab
    ---@type CommonGoodsListLight
    local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight, "Game.Behaviours.CommonGoodsListLight")
    if isNull(scr) then return end

    local childCount = self.Content.childCount
    for i = 0, childCount - 1, 1 do
        KTool.SetActive(self.Content:GetChild(i), false)
    end
    
    for i, data in ipairs(datas) do
        local go
        local tf = self.Content:Find("GoodNode"..i)
        if isNotNull(tf) then
            go = tf.gameObject
        end
        if isNull(go) then
            go = scr.poolBehaviour:GetPoolObject("GoodNode", self.Content.gameObject)
            go.name = "GoodNode"..i
            go.transform.pivot = Vector2.New(0.5, 0.5)
        end
        KTool.SetActive(go, true)
        scr:RefreshGoodNode(go, data, nil, nil, true, nil, nil, nil, false)
    end
end

return DropItemGroup